INSERT INTO ntss.sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, reg_date, up_date, system_use_disp) VALUES('3115', '抗凝固剤設定のデフォルト指定', '0', 3, '', '患者経過総合ビューア', 0, '・抗凝固剤ワンショット量</br>・抗凝固剤持続速度</br>・抗凝固剤持続総量(※1)</br>ON：上記項目が非表示だった場合、設定値を「0」とする。</br>OFF：上記項目設定値の変更は行わない。</br>※1 「抗凝固剤設定の自動計算指定」がＯＮの場合、「抗凝固剤持続総量」は自動計算された値が設定されます。', 115, '2021-02-09 10:06:07.000', '2021-02-09 10:06:07.000', '2');
INSERT INTO ntss.sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, reg_date, up_date, system_use_disp) VALUES('3116', '抗凝固剤設定の自動計算指定', '0', 3, '', '患者経過総合ビューア', 0, '・抗凝固剤持続総量</br>・IPワンショット量</br>・IP速度</br>以下の計算項目が非表示だった場合に、計算に関わる項目が変更された場合は計算ロジックに従い強制変更するかしないかの設定。</br>ON：上記項目が非表示だった場合、計算に関わる項目が変更された場合は計算ロジックに従い強制変更する。</br>OFF：上記項目設定値の変更は行わない。</br>※1 「抗凝固剤設定の自動計算指定」がＯＮの場合、「抗凝固剤持続総量」は自動計算された値が設定されます。', 116, '2021-02-09 10:06:07.000', '2021-02-09 10:06:07.000', '2');
INSERT INTO ntss.sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, reg_date, up_date, system_use_disp) VALUES('3113', '補液計算-補液比率有効化設定', '1', 3, '', '装置設定デフォルトマスタ</br>装置設定', 0, '・補液計算優先項目-補液比率</br>・補液比率</br>装置設定デフォルトマスタおよび装置設定にて上記項目のを表示/非表示切り替えます。</br>尚、補液計算優先項目にて「補液比率」をしている状態で当設定をＯＦＦにした場合、補液計算優先項目は「補液速度算出」に設定されます。</br>ＯＮ：上記内容を表示する</br>ＯＦＦ：上記内容を非表示にする。', 113, '2021-02-09 10:06:07.000', '2021-02-09 10:06:07.000', '2');
INSERT INTO ntss.sys_facility_setting (facility_setting_no, setting_name, default_value, input_type, option_value, function_name, maker_setting, description, disp_order, reg_date, up_date, system_use_disp) VALUES('3114', '補液計算-濾過率から算出有効化設定', '1', 3, '', '装置設定デフォルトマスタ</br>装置設定', 0, '・補液計算優先項目：濾過率から算出</br>・濾過率</br>・ヘマトクリット</br>・総タンパク</br>装置設定デフォルトマスタおよび装置設定にて上記項目のを表示/非表示切り替えます。</br>尚、補液計算優先項目にて「濾過率から算出」をしている状態で当設定をＯＦＦにした場合、補液計算優先項目は「補液速度算出」に設定されます。</br>ＯＮ：上記内容を表示する</br>ＯＦＦ：上記内容を非表示にする。', 114, '2021-02-09 10:06:07.000', '2021-02-09 10:06:07.000', '2');